window.products.push({"id":1073588,"name":"Sur La Table Garlic Peeler, Blue","category":"homeandappliances","retail price":9.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/51nvqHbhrFL._AC_SL1500_.jpg","description":"Garlic is an important ingredient in many of our favorite recipes, but all cooks hate the odor it leaves on their hands when preparing it. We love this tool for solving this problem and quickly peeling garlic cloves without passing the odor onto your hands. Just place clove inside garlic roller and hand on middle of roller, then push down and roll—it’s that simple. 1¾\" d x 1½\" h x 6\" l x 1½\" w. Dishwasher safe.","images":["https://m.media-amazon.com/images/I/51nvqHbhrFL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Sur La Table","source_asin":"B076DN46R9","category_path":"Home & Kitchen"},"sku":"BM-1073588","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B076DN46R9","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B076DN46R9","price_pending":true,"merchant_ready":false});
